// Slack does TWO things on this endpoint:
//   1) One-time URL verification: POST { type:'url_verification', challenge:'...' } — must echo challenge.
//   2) Real events: POST { type:'event_callback', event:{ ... } }
// We branch here and short-circuit verification.
//
// IMPORTANT: Slack's file_shared event does NOT include mime type — only file_id.
// We fetch full file metadata via Slack: Get File Info downstream, then Whisper handles
// non-audio gracefully (rejects with a clear API error).

const body = $input.first().json.body || $input.first().json;

if (body.type === 'url_verification') {
  return [{ json: { __verification: true, challenge: body.challenge } }];
}

const event = body.event;
if (!event || event.type !== 'file_shared') {
  return [{ json: { __skip: true, reason: 'Not a file_shared event' } }];
}

return [{ json: {
  __verification: false,
  __skip: false,
  file_id: event.file_id || event.file?.id,
  user_id: event.user_id,
  channel_id: event.channel_id || event.channel
} }];

// Reject silent / too-short / hallucinated transcripts before spending LLM tokens.
const t = $input.first().json;
const text = (t.text || '').trim();
const duration = t.duration || 0;

if (!text || text.length < 3) throw new Error('Empty transcript');
if (duration < 1.0) throw new Error(`Audio too short (${duration}s)`);
if (duration > 120) throw new Error(`Audio too long (${duration}s) — limit is 2 minutes per voice note`);

// Whisper sometimes hallucinates 'Thank you for watching.' on near-silent inputs.
const hallucinations = ['thank you for watching', 'thanks for watching', 'subscribe', 'subtitles by'];
if (hallucinations.some(h => text.toLowerCase().includes(h)) && text.length < 60) {
  throw new Error(`Likely Whisper hallucination on near-silent audio: "${text}"`);
}

// Pull through user context for memory.
const slack_meta = $('Route Slack Event').first().json;

return [{ json: {
  transcript: text,
  duration_seconds: duration,
  language: t.language,
  user_id: slack_meta.user_id,
  channel_id: slack_meta.channel_id
} }];

// Build an OpenAI function-calling request with conversation memory + tool definitions.

const current = $('Validate Transcript').first().json;
// Filter out empty placeholder rows that Always Output Data adds when there's no real history.
const history = $input.all()
  .filter(row => row.json && row.json.user_transcript)
  .reverse(); // oldest first

const system = `You are a CRM voice assistant. The user is on Slack and just left you a voice note. Decide what CRM action to take, or whether to answer a question.

Use a tool when the user asks for a CRM action. Confirm what you did in a single short sentence — this will be spoken aloud, so no markdown, no lists. Be concise (under 30 words).

If the user is asking a question or just chatting, answer without calling a tool.`;

// Convert history rows into OpenAI chat message turns.
const memory_messages = history.flatMap(row => {
  const r = row.json;
  const out = [{ role: 'user', content: r.user_transcript }];
  if (r.assistant_response) out.push({ role: 'assistant', content: r.assistant_response });
  return out;
});

const messages = [
  { role: 'system', content: system },
  ...memory_messages,
  { role: 'user', content: current.transcript }
];

// OpenAI function calling format: tools are wrapped { type: 'function', function: { ... parameters ... } }.
const tools = [
  {
    type: 'function',
    function: {
      name: 'create_contact',
      description: 'Create a new contact in the CRM.',
      parameters: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          company: { type: 'string' },
          email: { type: 'string' },
          notes: { type: 'string' }
        },
        required: ['name']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'log_activity',
      description: 'Log an activity (call, meeting, email) against an existing contact.',
      parameters: {
        type: 'object',
        properties: {
          contact_query: { type: 'string', description: 'Name or company to find the contact by' },
          activity_type: { type: 'string', enum: ['call','meeting','email','note'] },
          summary: { type: 'string' }
        },
        required: ['contact_query','activity_type','summary']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'query_contact',
      description: 'Look up information about a contact.',
      parameters: {
        type: 'object',
        properties: { query: { type: 'string' } },
        required: ['query']
      }
    }
  }
];

return [{ json: {
  ...current,
  openai_payload: {
    model: 'gpt-4o',
    max_tokens: 600,
    temperature: 0.4,
    messages,
    tools,
    tool_choice: 'auto'
  }
} }];

// Parse OpenAI's function-calling response. Either a tool_calls array or direct content.
// OpenAI's tool_calls is on choices[0].message.tool_calls; arguments is a STRING (must JSON.parse).
const resp = $input.first().json;
const current = $('Build OpenAI Request').first().json;

const choice = resp.choices?.[0];
if (!choice) throw new Error(`OpenAI returned no choices. Full: ${JSON.stringify(resp).slice(0, 500)}`);

const message = choice.message || {};
const finish_reason = choice.finish_reason;
const tool_calls = message.tool_calls || [];
const content = message.content;

const tokens_in = resp.usage?.prompt_tokens || 0;
const tokens_out = resp.usage?.completion_tokens || 0;

if (tool_calls.length > 0) {
  const call = tool_calls[0];
  let parsed_args;
  try { parsed_args = JSON.parse(call.function.arguments); }
  catch (e) { throw new Error(`Failed to parse tool arguments JSON: ${e.message}. Got: ${call.function.arguments}`); }
  return [{ json: {
    user_id: current.user_id,
    channel_id: current.channel_id,
    transcript: current.transcript,
    action: 'tool',
    tool_name: call.function.name,
    tool_input: parsed_args,
    tool_use_id: call.id,
    text_preamble: content || '',
    tokens_in, tokens_out
  } }];
}

if (content) {
  return [{ json: {
    user_id: current.user_id,
    channel_id: current.channel_id,
    transcript: current.transcript,
    action: 'reply',
    reply_text: content,
    tokens_in, tokens_out
  } }];
}

throw new Error(`OpenAI returned no usable content. finish_reason=${finish_reason}`);

// Synthesize a short spoken confirmation/result based on which tool ran.
// This is what gets spoken back to the user via ElevenLabs.
const src = $input.first().json;
const tool_result = src; // raw row(s) from Supabase

const priorCtx = $('Parse OpenAI Response').first().json;
const toolName = priorCtx.tool_name;
const toolInput = priorCtx.tool_input;

let spoken;
switch (toolName) {
  case 'create_contact':
    spoken = `Created contact for ${toolInput.name}${toolInput.company ? ' at ' + toolInput.company : ''}.`;
    break;
  case 'log_activity':
    spoken = `Logged a ${toolInput.activity_type} for ${toolInput.contact_query}.`;
    break;
  case 'query_contact': {
    const rows = Array.isArray(tool_result) ? tool_result : [tool_result];
    if (!rows.length || !rows[0].name) spoken = `I couldn't find anyone matching ${toolInput.query}.`;
    else if (rows.length === 1) spoken = `Found ${rows[0].name}${rows[0].company ? ' at ' + rows[0].company : ''}.${rows[0].notes ? ' Notes: ' + rows[0].notes.slice(0, 120) : ''}`;
    else spoken = `Found ${rows.length} matches. Top one: ${rows[0].name}${rows[0].company ? ' at ' + rows[0].company : ''}.`;
    break;
  }
  default:
    spoken = priorCtx.text_preamble || 'Done.';
}

return [{ json: {
  user_id: priorCtx.user_id,
  channel_id: priorCtx.channel_id,
  transcript: priorCtx.transcript,
  reply_text: spoken,
  tool_name: toolName,
  tokens_in: priorCtx.tokens_in,
  tokens_out: priorCtx.tokens_out
} }];
